// src/js/supabaseUpload.js
import { supabase } from "./supabaseConfig";

const BUCKET = "ChatWEB"; 

function normalizePublicUrl(data) {
  if (!data) return "";
  return data.publicUrl || data.public_url || data.publicURL || data.publicURL || data?.publicUrl || "";
}

export async function uploadAvatar(file, uid) {
  if (!file) return "";

  const filePath = `avatars/${uid}/${Date.now()}-${file.name}`;

  // upload
  const { error: uploadError } = await supabase.storage
    .from(BUCKET)
    .upload(filePath, file, {
      cacheControl: "3600",
      upsert: false
    });

  if (uploadError) {
    console.error("Erro no upload Supabase:", uploadError);
    throw uploadError;
  }

  // get public url
  try {
      const { data } = supabase.storage
    .from(BUCKET)
    .getPublicUrl(filePath);

  return {
    publicUrl: data.publicUrl,
    path: filePath // guarda path para possibilidade de remoção
  };

    const urlResponse = supabase.storage.from(BUCKET).getPublicUrl(filePath);
    let publicUrl = "";
    if (urlResponse?.data && (urlResponse.data.publicUrl || urlResponse.data.publicURL || urlResponse.data.public_url)) {
      publicUrl = normalizePublicUrl(urlResponse.data);
    } else if (urlResponse?.publicUrl || urlResponse?.publicURL || urlResponse?.public_url) {
      publicUrl = normalizePublicUrl(urlResponse);
    } else if (urlResponse?.data && typeof urlResponse.data === "object") {
      publicUrl = normalizePublicUrl(urlResponse.data);
    }

    if (!publicUrl) {
      publicUrl = normalizePublicUrl(urlResponse);
    }

    return publicUrl;
  } catch (err) {
    console.error("Erro ao obter publicUrl:", err);
    throw err;
  }
}

export async function uploadMessageMedia(file, roomId) {
  if (!file) return "";

  const filePath = `rooms/${roomId}/${Date.now()}-${file.name}`;

  const { error: uploadError } = await supabase.storage
    .from(BUCKET)
    .upload(filePath, file);

  if (uploadError) {
    console.error("Erro no upload Supabase:", uploadError);
    throw uploadError;
  }

  try {
    const urlResponse = supabase.storage.from(BUCKET).getPublicUrl(filePath);
    let publicUrl = "";
    if (urlResponse?.data && (urlResponse.data.publicUrl || urlResponse.data.publicURL || urlResponse.data.public_url)) {
      publicUrl = normalizePublicUrl(urlResponse.data);
    } else if (urlResponse?.publicUrl || urlResponse?.publicURL || urlResponse?.public_url) {
      publicUrl = normalizePublicUrl(urlResponse);
    } else {
      publicUrl = normalizePublicUrl(urlResponse);
    }
    return publicUrl;
  } catch (err) {
    console.error("Erro ao obter publicUrl:", err);
    throw err;
  }
}
